#!/usr/bin/env python3
"""Import both complete pinned NAF helper CFGs without instruction changes."""

import argparse
import hashlib
import json
from pathlib import Path


HERE = Path(__file__).resolve().parent
GENERATED = HERE.parent.parent / "MLIR/generated"


def generate():
    primary = json.loads((GENERATED / "manifest.json").read_text())
    output = [
        "module", "", "public import SSA.Projects.RIR.Syntax.Elab", "",
        "/-! Complete compiler-produced NAF helpers. Generated by import_program.py.",
        "No instructions, flags, indices, branches or aliases are rewritten.",
        "The import manifest pins the MLIR body and the primary extraction.",
        "Successful elaboration proves translation succeeds, not execution correctness.",
        "-/", "", "namespace Agave.Ed25519.NAF.RIR", "",
        "open LeanMLIR.RIR", "@[expose] public section", "",
    ]
    manifest = {}
    for width in (5, 8):
        name = f"agave_scalar_naf{width}"
        path = GENERATED / (name + ".mlir")
        source = path.read_text()
        digest = hashlib.sha256(path.read_bytes()).hexdigest()
        expected = primary["kernels"][name]["files_sha256"][path.name]
        if digest != expected:
            raise ValueError(f"primary-pinned NAF MLIR changed: {path}")
        start = source.index("  ^bb0(")
        end = source.index("\n  }) : () -> ()", start)
        body = source[start:end]
        if source.count("  ^bb0(") != 1:
            raise ValueError(f"expected one kernel definition: {path}")
        output += [f"mlir_def kernel{width} :=", "{", body, "}", ""]
        manifest[name] = {
            "source": str(path.relative_to(HERE.parent.parent)),
            "source_sha256": digest,
            "region_sha256": hashlib.sha256(body.encode()).hexdigest(),
            "normalizations": [],
        }
    output += ["end", "end Agave.Ed25519.NAF.RIR", ""]
    return "\n".join(output), json.dumps(manifest, indent=2) + "\n"


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    program, manifest = generate()
    for path, content in ((HERE / "Program.lean", program),
                          (HERE / "program-manifest.json", manifest)):
        if args.check:
            if path.read_text() != content:
                raise ValueError(f"stale NAF import: {path}")
        else:
            path.write_text(content)


if __name__ == "__main__":
    main()
